parameters.message:
=A document requires your review and approval.

Document: {{ $json.body.documentName }}
Submitted by: {{ $json.body.submittedBy }}
Date: {{ $json.body.submitDate || new Date().toISOString() }}

Please review the attached PDF and respond:
- Approve: POST to {{ $json.headers.host }}/webhook/approval-decision with { decision: 'approved', documentId: '{{ $json.body.documentId }}' }
- Reject: POST with { decision: 'rejected', reason: '...' }

parameters.jsCode:
const items = $input.all();
const results = [];
for (const item of items) {
  const decision = item.json.body.decision;
  const documentId = item.json.body.documentId;
  const approver = item.json.body.approverName || 'Reviewer';
  const reason = item.json.body.reason || '';
  const stampText = decision === 'approved'
    ? `APPROVED by ${approver} on ${new Date().toISOString()}`
    : `REJECTED by ${approver} on ${new Date().toISOString()} - Reason: ${reason}`;
  results.push({
    json: {
      documentId,
      decision,
      approver,
      reason,
      stampText,
      timestamp: new Date().toISOString(),
      status: decision === 'approved' ? 'FINAL' : 'RETURNED'
    }
  });
}
return results;
